<?php function settingValue(array $settings,string $key,string $default=''):string{return (string)($settings[$key]['value']??$default);} ?>
<div class="page-heading admin-heading"><div><span class="eyebrow">Configuration</span><h1>College & admission settings</h1><p>Institution identity, privacy controls, payment instructions and intake setup.</p></div></div><form method="post" action="<?= url('admin/settings') ?>" class="settings-layout"><?= csrf_field() ?><nav class="settings-nav"><a href="#identity" class="active">College identity</a><a href="#admission">Admission policy</a><a href="#payment">Payment details</a><a href="#cycles">Cycles & programmes</a><a href="#security">Security & privacy</a></nav><div class="settings-content"><section class="card settings-section" id="identity"><div class="section-title"><div><span class="eyebrow">Public identity</span><h2>College details</h2></div></div><div class="form-grid"><label><span>College name</span><input name="college_name" value="<?= e(settingValue($settings,'college_name','Netaji College of Pharmacy')) ?>"></label><label><span>Short name</span><input name="college_short_name" value="<?= e(settingValue($settings,'college_short_name','NCP')) ?>"></label><label><span>Public email</span><input type="email" name="college_email" value="<?= e(settingValue($settings,'college_email')) ?>"></label><label><span>Public phone</span><input name="college_phone" value="<?= e(settingValue($settings,'college_phone')) ?>"></label><label class="full"><span>Address</span><textarea name="college_address" rows="3"><?= e(settingValue($settings,'college_address')) ?></textarea></label><label><span>Brand colour</span><input type="color" name="primary_color" value="<?= e(settingValue($settings,'primary_color','#075e61')) ?>"></label></div><div class="compliance-callout"><b>Regulatory content remains unclaimed.</b><p>Add only verified affiliation, university, PCI/AICTE approval and sanctioned-intake data supported by official records.</p></div></section><section class="card settings-section" id="admission"><div class="section-title"><div><span class="eyebrow">Sensitive data</span><h2>Aadhaar collection stage</h2></div></div><label><span>Collection policy</span><select name="aadhaar_collection_stage"><option value="disabled"<?= selected(settingValue($settings,'aadhaar_collection_stage'),'disabled') ?>>Do not collect</option><option value="application"<?= selected(settingValue($settings,'aadhaar_collection_stage'),'application') ?>>Initial application (requires legal review)</option><option value="post_selection"<?= selected(settingValue($settings,'aadhaar_collection_stage'),'post_selection') ?>>After selection</option><option value="admission"<?= selected(settingValue($settings,'aadhaar_collection_stage'),'admission') ?>>At admission</option><option value="configurable"<?= selected(settingValue($settings,'aadhaar_collection_stage'),'configurable') ?>>Configured per intake</option></select></label><div class="warning-box"><span>!</span><div><b>Compliance acknowledgement required</b><p>Collecting Aadhaar is not automatically lawful for every institution or purpose. Confirm authority, purpose, consent, access and retention with qualified counsel before enabling it.</p></div></div><label class="check-control"><input type="checkbox" name="aadhaar_compliance_ack" value="1"><span>I confirm that the institution has documented a lawful purpose, approved privacy notice, restricted access, consent process and retention schedule for the selected policy.</span></label><label><span>Privacy contact email</span><input type="email" name="privacy_contact" value="<?= e(settingValue($settings,'privacy_contact')) ?>"></label></section><section class="card settings-section" id="payment"><div class="section-title"><div><span class="eyebrow">Manual verification</span><h2>Payment instructions</h2></div></div><div class="form-grid"><label><span>UPI ID</span><input name="upi_id" value="<?= e(settingValue($settings,'upi_id')) ?>" placeholder="college@bank"></label><label class="full"><span>Bank and beneficiary details</span><textarea name="bank_details" rows="5"><?= e(settingValue($settings,'bank_details')) ?></textarea></label></div></section><section class="card settings-section" id="cycles"><div class="section-title"><div><span class="eyebrow">Admissions</span><h2>Cycles & programmes</h2></div></div><div class="config-create-grid"><details><summary>+ Create programme</summary><div><label><span>Name</span><input form="create-program" name="name" required placeholder="Master of Pharmacy"></label><label><span>Code</span><input form="create-program" name="code" required placeholder="MPHARM"></label><label><span>Award type</span><input form="create-program" name="award_type" value="Undergraduate Degree"></label><label><span>Duration (years)</span><input form="create-program" type="number" step=".5" name="duration_years" value="4"></label><label><span>Semesters</span><input form="create-program" type="number" name="total_semesters" value="8"></label><label class="wide"><span>Public summary</span><textarea form="create-program" name="summary" rows="2"></textarea></label><button form="create-program" class="button button-primary button-sm">Create programme</button></div></details><details><summary>+ Create admission cycle</summary><div><label><span>Session name</span><input form="create-cycle" name="session_name" required placeholder="2028–29"></label><label><span>Cycle name</span><input form="create-cycle" name="cycle_name" required placeholder="Undergraduate Admissions 2028–29"></label><label><span>Cycle code</span><input form="create-cycle" name="cycle_code" required placeholder="UG-2028"></label><label><span>Session starts</span><input form="create-cycle" type="date" name="session_starts_on" required></label><label><span>Session ends</span><input form="create-cycle" type="date" name="session_ends_on" required></label><label><span>Applications open</span><input form="create-cycle" type="datetime-local" name="starts_at" required></label><label><span>Applications close</span><input form="create-cycle" type="datetime-local" name="ends_at" required></label><button form="create-cycle" class="button button-primary button-sm">Create draft cycle</button></div></details></div><div class="setting-records detailed"><?php foreach($cycles as $cycle): $cycleForm='cycle-'.$cycle['id'];?><details><summary><div><b><?= e($cycle['name']) ?></b><small><?= e($cycle['code']) ?> · <?= format_date($cycle['starts_at']) ?> to <?= format_date($cycle['ends_at']) ?></small></div><span class="status-pill status-<?= e($cycle['status']) ?>"><?= e(ucfirst($cycle['status'])) ?></span><i>Edit</i></summary><div class="setting-edit-grid"><label><span>Cycle name</span><input form="<?= e($cycleForm) ?>" name="name" value="<?= e($cycle['name']) ?>"></label><label><span>Status</span><select form="<?= e($cycleForm) ?>" name="status"><?php foreach(['draft','open','closed','processing','archived'] as $option):?><option value="<?= $option ?>"<?= selected($cycle['status'],$option) ?>><?= e(ucfirst($option)) ?></option><?php endforeach?></select></label><label><span>Opens</span><input form="<?= e($cycleForm) ?>" type="datetime-local" name="starts_at" value="<?= e(date('Y-m-d\TH:i',strtotime($cycle['starts_at']))) ?>"></label><label><span>Closes</span><input form="<?= e($cycleForm) ?>" type="datetime-local" name="ends_at" value="<?= e(date('Y-m-d\TH:i',strtotime($cycle['ends_at']))) ?>"></label><label><span>Correction deadline</span><input form="<?= e($cycleForm) ?>" type="datetime-local" name="correction_deadline" value="<?= $cycle['correction_deadline']?e(date('Y-m-d\TH:i',strtotime($cycle['correction_deadline']))):'' ?>"></label><label><span>Aadhaar stage for this intake</span><select form="<?= e($cycleForm) ?>" name="aadhaar_collection_stage"><option value="disabled"<?= selected(settingValue($settings,'aadhaar_collection_stage_cycle_'.$cycle['id'],'disabled'),'disabled') ?>>Do not collect</option><option value="application"<?= selected(settingValue($settings,'aadhaar_collection_stage_cycle_'.$cycle['id']),'application') ?>>Application<