on button-primary button-sm">Save intake rules</button></div></details><?php endforeach?></div><h3 class="settings-subtitle">Seat matrix</h3><div class="inline-config-list"><?php foreach($seatMatrix as $seat): $seatForm='seat-'.$seat['id'];?><div><span><b><?= e($seat['category']) ?></b><small><?= e($seat['quota']) ?> · <?= e($seat['program_name']) ?></small></span><input form="<?= e($seatForm) ?>" type="number" min="<?= e($seat['filled_seats']) ?>" name="seats" value="<?= e($seat['seats']) ?>"><button form="<?= e($seatForm) ?>">Save</button></div><?php endforeach?></div><h3 class="settings-subtitle">Document checklist</h3><div class="inline-config-list docs"><?php foreach($documentRequirements as $requirement): $docForm='document-'.$requirement['id'];?><div><span><b><?= e($requirement['document_name']) ?></b><small>Checklist order <?= e($requirement['sort_order']) ?></small></span><label class="check-control"><input form="<?= e($docForm) ?>" type="checkbox" name="is_required" value="1" <?= checked($requirement['is_required']) ?>><span>Required</span></label><select form="<?= e($docForm) ?>" name="stage"><option value="application"<?= selected($requirement['stage'],'application') ?>>Application</option><option value="admission"<?= selected($requirement['stage'],'admission') ?>>Admission</option></select><button form="<?= e($docForm) ?>">Save</button></div><?php endforeach?></div></section><section class="card settings-section" id="security"><div class="section-title"><div><span class="eyebrow">Production baseline</span><h2>Security status</h2></div></div><div class="security-checks"><div><i>✓</i><span><b>Protected private storage</b><small>Uploads are streamed through authorisation checks</small></span></div><div><i>✓</i><span><b>AES-256-GCM field encryption</b><small>Configured identity values use the application key</small></span></div><div><i>✓</i><span><b>Staff email MFA</b><small>Required when enabled in environment settings</small></span></div><div><i>✓</i><spa